from pathlib import Path
import json
root=Path('/private/tmp/ctrl-reality-original-candidates')
common=r'''export default function generate(THREE){
 const g=new THREE.Group();const ivory=new THREE.MeshStandardMaterial({color:0xe7e1d5,metalness:.14,roughness:.38}),obsidian=new THREE.MeshStandardMaterial({color:0x10151c,metalness:.5,roughness:.27}),bronze=new THREE.MeshStandardMaterial({color:0xc99a4a,metalness:.65,roughness:.30}),cyan=new THREE.MeshStandardMaterial({color:0x56e8f2,emissive:0x56e8f2,emissiveIntensity:.7,metalness:.3,roughness:.25});ivory.name='stone';obsidian.name=bronze.name='metal';cyan.name='interface';
 function mesh(geo,mat,p=g,x=0,y=0,z=0){const m=new THREE.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;p.add(m);return m;}
 function group(name,p=g){const n=new THREE.Group();n.name=name;p.add(n);return n;}
 function path(points,mat,r=.025,p=g){const c=new THREE.CatmullRomCurve3(points.map(v=>new THREE.Vector3(...v)));return mesh(new THREE.TubeGeometry(c,Math.max(12,points.length*5),r,5,false),mat,p);}
 function extrude(shape,depth,mat,p=g,x=0,y=0,z=0,bevel=.018){return mesh(new THREE.ExtrudeGeometry(shape,{depth,steps:1,bevelEnabled:bevel>0,bevelSize:bevel,bevelThickness:bevel,bevelSegments:2,curveSegments:20}),mat,p,x,y,z);}
 function polygon(points){const s=new THREE.Shape();points.forEach(([x,y],i)=>i?s.lineTo(x,y):s.moveTo(x,y));s.closePath();return s;}
 function rounded(w,h,r){const s=new THREE.Shape();s.moveTo(-w/2+r,-h/2);s.lineTo(w/2-r,-h/2);s.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);s.lineTo(w/2,h/2-r);s.quadraticCurveTo(w/2,h/2,w/2-r,h/2);s.lineTo(-w/2+r,h/2);s.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);s.lineTo(-w/2,-h/2+r);s.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);return s;}
 function archShape(outer,inner,height){const s=new THREE.Shape();s.moveTo(-outer,0);s.lineTo(-outer,height*.39);s.bezierCurveTo(-outer,height*.69,-outer*.55,height*.87,0,height);s.bezierCurveTo(outer*.55,height*.87,outer,height*.69,outer,height*.39);s.lineTo(outer,0);s.lineTo(inner,0);s.lineTo(inner,height*.39);s.bezierCurveTo(inner,height*.64,inner*.52,height*.79,0,height-(outer-inner)*1.35);s.bezierCurveTo(-inner*.52,height*.79,-inner,height*.64,-inner,height*.39);s.lineTo(-inner,0);s.closePath();return s;}
 function ring(radius,thickness,mat,p=g){return mesh(new THREE.TorusGeometry(radius,thickness,8,72),mat,p);}
 /* BUILD */
 g.updateMatrixWorld(true);const box=new THREE.Box3(),v=new THREE.Vector3();g.traverse(o=>{if(o.isMesh){const a=o.geometry.attributes.position;for(let i=0;i<a.count;i++)box.expandByPoint(v.fromBufferAttribute(a,i).applyMatrix4(o.matrixWorld));}});const center=box.getCenter(new THREE.Vector3());for(const c of g.children){c.position.x-=center.x;c.position.y-=box.min.y;c.position.z-=center.z;}g.userData.family='FAMILY';g.userData.strategy='STRATEGY';return g;
}
'''
def family(name,variants,expected=None):
 d=root/name;d.mkdir(exist_ok=True)
 for i,(strategy,code)in enumerate(variants,1):
  f=d/f'{i:02d}-{strategy}.js';f.write_text(common.replace('/* BUILD */',code).replace('FAMILY',name).replace('STRATEGY',strategy))
  if expected:(d/(f.stem+'.expect.json')).write_text(json.dumps(expected))
 (d/'PROCESS.md').write_text('# '+name+' — 404 path B\n\nClean reference: production/visual-lock/references/'+name+'.jpg. Shared style: docs/VISUAL_STYLE_LOCK.md.\n\n'+''.join(f'{i}. {s}: separate construction, not a parameter-only variation.\n'for i,(s,c)in enumerate(variants,1))+'\nOfficial multi-angle verification and visual selection required.\n')
