 ('split-petals',r'''const baseProfile=[[.0,0],[.26,0],[.28,.035],[.27,.078],[.21,.12],[.16,.23],[.13,.52],[.14,.77],[.18,.91]];mesh(new THREE.LatheGeometry(baseProfile.map(([x,y])=>new THREE.Vector2(x,y)),40),obsidian);for(const offset of [0,Math.PI]){const pts=[],ix=[],N=24,M=18;for(let j=0;j<=M;j++){const v=j/M,y=.08+v*.86,r=.24-.115*Math.sin(v*Math.PI)+.012*v;for(let i=0;i<=N;i++){const u=i/N,a=offset+u*2.3+v*.85;pts.push(Math.sin(a)*r,y,Math.cos(a)*r);}}for(let j=0;j<M;j++)for(let i=0;i<N;i++){let k=j*(N+1)+i;ix.push(k,k+1,k+N+1,k+1,k+N+2,k+N+1);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(pts,3));geo.setIndex(ix);geo.computeVertexNormals();const shell=mesh(geo,ivory);shell.material=ivory.clone();shell.material.side=THREE.DoubleSide;path(Array.from({length:14},(_,i)=>{const v=i/13,r=.242-.115*Math.sin(v*Math.PI)+.012*v,a=offset+v*.85;return[Math.sin(a)*r,.08+v*.86,Math.cos(a)*r];}),bronze,.005);}for(const y of [.025,.075]){const m=ring(.268,.006,bronze);m.rotation.x=Math.PI/2;m.position.y=y;}'''+receptacle),
 ('carved-shells',r'''const s=new THREE.Shape();s.moveTo(-.23,.08);s.bezierCurveTo(-.16,.25,-.09,.46,-.19,.87);s.lineTo(-.12,.98);s.bezierCurveTo(.1,.75,.08,.38,.23,.08);s.closePath();for(const sign of [-1,1]){const m=extrude(s,.105,ivory,g,0,0,sign*.10,.015);m.rotation.y=sign*.28;}mesh(new THREE.CylinderGeometry(.26,.28,.07,40),ivory,g,0,.035,0);path([[-.20,.1,.165],[-.10,.45,.15],[-.17,.91,.09]],bronze,.006);path([[.2,.1,-.165],[.1,.45,-.15],[.17,.91,-.09]],bronze,.006);'''+receptacle),
